using System;
using FFmpeg.AutoGen;
using UnityEngine;

namespace Hactazia.FFplay {
	/// <summary>
	/// Structure pour une frame vidéo décodée et convertie (équivalent VideoPicture de ffplay.c)
	/// Contient les données RGB prêtes pour affichage dans Unity
	/// </summary>
	public unsafe class VideoFrame {
		public byte[] Data;           // Données RGB/RGBA
		public int Width;
		public int Height;
		public double Pts;            // Presentation timestamp
		public double Duration;       // Durée de la frame
		public int Serial;            // Serial pour gérer les seeks
		public long Pos;              // Position dans le fichier

		public VideoFrame(int width, int height) {
			Width = width;
			Height = height;
			Data = new byte[width * height * 4]; // RGBA
		}
	}

	/// <summary>
	/// Queue circulaire de frames vidéo (équivalent FrameQueue de ffplay.c)
	/// Permet le découplage entre décodage et affichage
	/// </summary>
	public class VideoFrameQueue {
		private readonly VideoFrame[] _queue;
		private readonly object _lock = new();
		private int _size;
		private int _rindex;  // Index de lecture
		private int _windex;  // Index d'écriture
		private int _maxSize;
		private bool _abortRequest;

		public VideoFrameQueue(int maxSize = 3) {
			_maxSize = maxSize;
			_queue = new VideoFrame[maxSize];
		}

		/// <summary>
		/// Obtient la frame courante pour affichage
		/// </summary>
		public VideoFrame Peek() {
			lock (_lock) {
				if (_size == 0) return null;
				return _queue[_rindex];
			}
		}

		/// <summary>
		/// Obtient la prochaine frame (regarde en avance)
		/// </summary>
		public VideoFrame PeekNext() {
			lock (_lock) {
				if (_size < 2) return null;
				return _queue[(_rindex + 1) % _maxSize];
			}
		}

		/// <summary>
		/// Avance à la frame suivante (consomme)
		/// </summary>
		public void Next() {
			lock (_lock) {
				if (_size == 0) return;
				_rindex = (_rindex + 1) % _maxSize;
				_size--;
				System.Threading.Monitor.PulseAll(_lock);
			}
		}

		/// <summary>
		/// Alloue une frame pour écriture (producteur)
		/// </summary>
		public VideoFrame PeekWritable() {
			lock (_lock) {
				while (_size >= _maxSize && !_abortRequest) {
					System.Threading.Monitor.Wait(_lock, 10);
				}

				if (_abortRequest) return null;

				var frame = _queue[_windex];
				if (frame == null) {
					// Allouer au besoin
					frame = new VideoFrame(1920, 1080); // Taille par défaut, sera redimensionné
					_queue[_windex] = frame;
				}
				return frame;
			}
		}

		/// <summary>
		/// Valide l'écriture de la frame (producteur)
		/// </summary>
		public void Push() {
			lock (_lock) {
				_windex = (_windex + 1) % _maxSize;
				_size++;
				System.Threading.Monitor.PulseAll(_lock);
			}
		}

		/// <summary>
		/// Obtient le nombre de frames dans la queue
		/// </summary>
		public int NbRemaining() {
			lock (_lock) {
				return _size;
			}
		}

		/// <summary>
		/// Vide la queue
		/// </summary>
		public void Flush() {
			lock (_lock) {
				_rindex = 0;
				_windex = 0;
				_size = 0;
				System.Threading.Monitor.PulseAll(_lock);
			}
		}

		/// <summary>
		/// Signale l'arrêt de la queue
		/// </summary>
		public void Abort() {
			lock (_lock) {
				_abortRequest = true;
				System.Threading.Monitor.PulseAll(_lock);
			}
		}

		/// <summary>
		/// Redémarre la queue
		/// </summary>
		public void Start() {
			lock (_lock) {
				_abortRequest = false;
			}
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.Serialization;
using Cysharp.Threading.Tasks;
using Newtonsoft.Json.Linq;
using Nox.CCK.Mods.Events;
using Nox.CCK.Utils;

namespace Nox.Control.Handlers {
	public class EventHandler {
		public static void OnEvent(EventData context) {
			var clients = Main.Server.GetClients();

			var data = new List<JToken>();

			foreach (var d in context.Data) {
				switch (d) {
					case null:
						data.Add(JValue.CreateNull());
						break;

					case JToken jToken:
						data.Add(jToken);
						break;

					case ISerializable serializable:
						data.Add(JToken.FromObject(serializable));
						break;

					default:
						data.Add(JToken.FromObject(d.ToString()));
						break;
				}
			}

			var channels = (
			from EventEntryFlags flag
				in Enum.GetValues(typeof(EventEntryFlags))
			where context.SourceChannel.HasFlag(flag)
			select flag.ToString().ToSnakeCase()
			).ToArray();

			foreach (var client in clients)
				client.Send("event", context.EventName, context.Source.GetMetadata().GetId(), data.ToArray(), channels).Forget();
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.Serialization;
using Cysharp.Threading.Tasks;
using Newtonsoft.Json.Linq;
using Nox.CCK.Mods.Events;
using Nox.CCK.Utils;

namespace Nox.Control.Handlers {
	public class EventHandler {
		public static void OnEvent(EventData context) {
			if (Main.Server == null || !Main.Server.IsRunning()) return;

			var clients = Main.Server.GetClients();

			var data = new List<JToken>();

			foreach (var d in context.Data) {
				switch (d) {
					case null:
						data.Add(JValue.CreateNull());
						break;

					case JToken jToken:
						data.Add(jToken);
						break;

					case ISerializable serializable:
						data.Add(JToken.FromObject(serializable));
						break;

					default:
						data.Add(JToken.FromObject(d.ToString()));
						break;
				}
			}

			var channels = (
			from EventEntryFlags flag
				in Enum.GetValues(typeof(EventEntryFlags))
			where context.SourceChannel.HasFlag(flag)
			select flag.ToString().ToSnakeCase()
			).ToArray();

			foreach (var client in clients) {
				if (client.IsConnected())
					client.Send("event", context.EventName, context.Source.GetMetadata().GetId(), data.ToArray(), channels).Forget();
			}
		}
	}
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using Cysharp.Threading.Tasks;
using Nox.SDK.Control;
using UnityEngine;
using Logger = Nox.CCK.Utils.Logger;
using LogType = Nox.CCK.Utils.LogType;
using Object = UnityEngine.Object;

namespace Nox.Control.Handlers {
	public class LoggerHandler {
		public static void Listen() {
			Logger.OnProgress.AddListener(OnProgress);
			Logger.OnLog.AddListener(OnLog);
		}

		public static void Handle(IClient client, string eventName, params object[] args) {
			if (eventName != "logger:history") return;
			var timestamp = args.Length > 0 && args[0] is int
				? DateTimeOffset.FromUnixTimeMilliseconds(long.Parse(args[0].ToString())).UtcDateTime
				: DateTime.MinValue;
			SendHistory(client, timestamp).Forget();
		}

		private static async UniTaskVoid SendHistory(IClient client, DateTime since) {
			var logs = Logger.History.Where(log => log.Timestamp >= since);
			await client.Send(
				"logger:history",
				logs.Select(
						log => new {
							type      = log.Type.ToString(),
							tag       = log.Tag,
							message   = log.Message,
							timestamp = new DateTimeOffset(log.Timestamp).ToUnixTimeMilliseconds()
						}
					)
					.ToArray<object>()
			);
		}


		private static void OnLog(LogType type, string message, string tag, Object context) {
			var clients = Main.Server.GetClients();
			foreach (var client in clients)
				client.Send("logger:log", type.ToString(), tag, message).Forget();
		}

		private static void OnProgress(bool active, string title, string message, float progress) {
			var clients = Main.Server.GetClients();
			foreach (var client in clients)
				client.Send("logger:progress", active, title, message, progress).Forget();
		}

		public static void Dispose() {
			Logger.OnProgress.RemoveListener(OnProgress);
			Logger.OnLog.RemoveListener(OnLog);
		}
	}
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using Cysharp.Threading.Tasks;
using Nox.SDK.Control;
using UnityEngine;
using Logger = Nox.CCK.Utils.Logger;
using LogType = Nox.CCK.Utils.LogType;
using Object = UnityEngine.Object;

namespace Nox.Control.Handlers {
	public class LoggerHandler {
		public static void Listen() {
			Logger.OnProgress.AddListener(OnProgress);
			Logger.OnLog.AddListener(OnLog);
		}

		public static void Handle(IClient client, string eventName, params object[] args) {
			if (eventName != "logger:history") return;
			var timestamp = args.Length > 0 && args[0] is int
				? DateTimeOffset.FromUnixTimeMilliseconds(long.Parse(args[0].ToString())).UtcDateTime
				: DateTime.MinValue;
			SendHistory(client, timestamp).Forget();
		}

		private static async UniTaskVoid SendHistory(IClient client, DateTime since) {
			var logs = Logger.History.Where(log => log.Timestamp >= since);
			await client.Send(
				"logger:history",
				logs.Select(
						log => new {
							type      = log.Type.ToString(),
							tag       = log.Tag,
							message   = log.Message,
							timestamp = new DateTimeOffset(log.Timestamp).ToUnixTimeMilliseconds()
						}
					)
					.ToArray<object>()
			);
		}


		private static void OnLog(LogType type, string message, string tag, Object context) {
			if (Main.Server == null || !Main.Server.IsRunning()) return;

			var clients = Main.Server.GetClients();
			foreach (var client in clients) {
				if (client.IsConnected())
					client.Send("logger:log", type.ToString(), tag, message).Forget();
			}
		}

		private static void OnProgress(bool active, string title, string message, float progress) {
			if (Main.Server == null || !Main.Server.IsRunning()) return;

			var clients = Main.Server.GetClients();
			foreach (var client in clients) {
				if (client.IsConnected())
					client.Send("logger:progress", active, title, message, progress).Forget();
			}
		}

		public static void Dispose() {
			Logger.OnProgress.RemoveListener(OnProgress);
			Logger.OnLog.RemoveListener(OnLog);
		}
	}
}
